using OcctSharp.DocumentAssociations;
using OcctSharp.DocumentProjections;
using OcctSharp.Tests.Shared;
namespace OcctSharp.Runtime.Tests;
public sealed class DocumentAssociationTests {
 [Fact]public void CompleteNamingReferenceAssemblyDimensionClippingPersistenceWorkflow()=>BatchBCAssociationWorkflow.Run();
 [Fact]public void EmptyDiagnosticsDoNotInitializeXcafToolsAndSurviveOwnerDisposal(){using var doc=DocumentAssociationContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var associations=DocumentAssociationContext.Bind(context);var label=context.GetLabel("0:1");var value=associations.Snapshot(label);Assert.Null(value.Naming);Assert.Null(value.Assembly);Assert.Null(value.Dimension);Assert.Null(value.Clipping);Assert.Null(value.ReferenceEntry);Assert.Empty(value.ClippingPlaneEntries);Assert.Equal(value.AttributeCount,value.AttributeIds.Count);doc.Dispose();Assert.Equal("0:1",value.Entry);Assert.Throws<ObjectDisposedException>(()=>associations.Snapshot(label));}
 [Fact]public void SameDocumentDifferentContextLabelsAndForeignDocumentLabelsFailBeforeMutation(){using var doc=DocumentAssociationContext.CreateNativeDocument();using var other=DocumentProjectionContext.CreateNativeDocument();using var a=DocumentProjectionContext.Bind(doc);using var b=DocumentProjectionContext.Bind(doc);using var c=DocumentProjectionContext.Bind(other);using var associations=DocumentAssociationContext.Bind(a);var own=a.GetLabel("0:1");doc.NewCommand();Assert.Throws<ArgumentException>(()=>associations.ReplaceReferences([new(own,b.GetLabel("0:1"))]));Assert.Throws<ArgumentException>(()=>associations.ReplaceReferences([new(own,c.GetLabel("0:1"))]));Assert.Null(associations.Snapshot(own).ReferenceEntry);doc.AbortCommand();}
 [Fact]public void MutationRequiresOpenCommandAndCannotPublishBorrowedLabels(){using var doc=DocumentAssociationContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var associations=DocumentAssociationContext.Bind(context);var label=context.GetLabel("0:1");Assert.ThrowsAny<Exception>(()=>associations.NewChild(label));Assert.ThrowsAny<Exception>(()=>associations.ReplaceReferences([new(label,label)]));Assert.ThrowsAny<Exception>(()=>associations.CreateClippingPlane("clip",new(0,0,1,0)));Assert.Null(associations.Snapshot(label).ReferenceEntry);}
 [Fact]public void LazyReferenceBudgetDisposesEnumeratorAndPublishesNoPrefix(){using var doc=DocumentAssociationContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var associations=DocumentAssociationContext.Bind(context);var label=context.GetLabel("0:1");bool disposed=false;int visits=0;IEnumerable<ReferenceUpdate> Rows(){try{while(true){visits++;yield return new(label,label);}}finally{disposed=true;}}doc.NewCommand();Assert.Throws<ArgumentOutOfRangeException>(()=>associations.ReplaceReferences(Rows()));Assert.True(disposed);Assert.Equal(4097,visits);Assert.Null(associations.Snapshot(label).ReferenceEntry);doc.AbortCommand();}
 [Fact]public void GenericReferenceBulkUndoRedoAndFailureAreAtomic(){using var doc=DocumentAssociationContext.CreateNativeDocument();doc.SetUndoLimit(10);using var context=DocumentProjectionContext.Bind(doc);using var associations=DocumentAssociationContext.Bind(context);var main=context.GetLabel("0:1");doc.NewCommand();var first=associations.NewChild(main);var second=associations.NewChild(main);associations.ReplaceReferences([new(first,main),new(second,first)]);Assert.True(doc.CommitCommand());Assert.Equal(main.Entry,associations.Snapshot(first).ReferenceEntry);doc.NewCommand();associations.ReplaceReferences([new(first,null),new(second,main)]);Assert.True(doc.CommitCommand());Assert.True(doc.Undo());Assert.Equal(main.Entry,associations.Snapshot(first).ReferenceEntry);Assert.Equal(first.Entry,associations.Snapshot(second).ReferenceEntry);Assert.True(doc.Redo());Assert.Null(associations.Snapshot(first).ReferenceEntry);Assert.Equal(main.Entry,associations.Snapshot(second).ReferenceEntry);doc.NewCommand();Assert.Throws<ArgumentException>(()=>associations.ReplaceReferences([new(first,main),new(first,second)]));Assert.Null(associations.Snapshot(first).ReferenceEntry);doc.AbortCommand();}
 [Fact]public void NonfiniteDegeneratePlanesAndInvalidAssociationTargetsFailAtomically(){using var doc=DocumentAssociationContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var associations=DocumentAssociationContext.Bind(context);var main=context.GetLabel("0:1");doc.NewCommand();Assert.ThrowsAny<Exception>(()=>associations.CreateClippingPlane("clip",new(0,0,0,0)));Assert.Throws<ArgumentOutOfRangeException>(()=>associations.CreateClippingPlane("clip",new(0,0,1,double.NaN)));Assert.ThrowsAny<Exception>(()=>associations.CreateDimensionAssociation("invalid",main));Assert.ThrowsAny<Exception>(()=>associations.SetViewClippingPlanes(main,[]));Assert.ThrowsAny<Exception>(()=>associations.CreateDirectNamingReference(main,main));doc.AbortCommand();Assert.Null(associations.Snapshot(main).Dimension);Assert.Null(associations.Snapshot(main).Naming);}
 [Fact]public void ClippingUpdateAbortKeepsExactCoefficientsNameAndCapping(){using var doc=DocumentAssociationContext.CreateNativeDocument();doc.SetUndoLimit(10);using var context=DocumentProjectionContext.Bind(doc);using var associations=DocumentAssociationContext.Bind(context);doc.NewCommand();var clip=associations.CreateClippingPlane("initial",new(0,0,1,-2),true);Assert.True(doc.CommitCommand());doc.NewCommand();associations.UpdateClippingPlane(clip,"edited",new(1,0,0,-5),false);Assert.False(associations.Snapshot(clip).Clipping!.IsCapping);doc.AbortCommand();var value=associations.Snapshot(clip).Clipping!;Assert.Equal("initial",value.Name);Assert.True(value.IsCapping);Assert.Equal(new PlaneCoefficients(0,0,1,-2),value.Plane);}
 [Fact]public void IndependentDocumentsCanReadDetachedAssociationSnapshotsConcurrently(){Parallel.For(0,8,_=>{using var doc=DocumentAssociationContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var associations=DocumentAssociationContext.Bind(context);doc.NewCommand();var label=associations.NewChild(context.GetLabel("0:1"));associations.ReplaceReferences([new(label,label)]);Assert.True(doc.CommitCommand());var value=associations.Snapshot(label);doc.Dispose();Assert.Equal(label.Entry,value.ReferenceEntry);});}
 [Fact]public void PinnedSdkParallelPlaneNameCollisionCannotRetargetOrChangeCapping(){using var doc=DocumentAssociationContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var associations=DocumentAssociationContext.Bind(context);doc.NewCommand();var clip=associations.CreateClippingPlane("parallel",new(0,0,1,-1),true);Assert.ThrowsAny<Exception>(()=>associations.CreateClippingPlane("parallel",new(0,0,1,-2),false));var value=associations.Snapshot(clip).Clipping!;Assert.True(value.IsCapping);Assert.Equal(-1,value.Plane.D);Assert.True(doc.CommitCommand());}
 [Fact]public void UnsafeGeneratedDocumentCannotEnterClippingOrNamingHistory(){using var doc=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var associations=DocumentAssociationContext.Bind(context);var main=context.GetLabel("0:1");doc.NewCommand();var clip=Assert.ThrowsAny<Exception>(()=>associations.CreateClippingPlane("unsafe",new(0,0,1,-1),true));Assert.Contains("close-safe",clip.Message,StringComparison.Ordinal);var naming=Assert.ThrowsAny<Exception>(()=>associations.CreateDirectNamingReference(main,main));Assert.Contains("close-safe",naming.Message,StringComparison.Ordinal);Assert.Null(associations.Snapshot(main).Clipping);doc.AbortCommand();}
}
